function rtState(g=game){if(!g)return null;g.vsxRoyalThree||={growthOverride:null,mbappe:null,vini:null,jude:null};if(!g.vsxRoyalThree.mbappe)g.vsxRoyalThree.mbappe={space:20,lastX:g.player?.x||0,lastY:g.player?.y||0,lastAng:null,lastHit:-99,line:null,lineCd:2.5,openUntil:0,secondGearUntil:0,lastMan:null,route:[],ult:null,breaks:0,offside:0,steady:0,firstStepReady:false,firstStepUntil:0,ultBoostUntil:0};if(!g.vsxRoyalThree.vini)g.vsxRoyalThree.vini={heat:15,lastX:g.player?.x||0,lastY:g.player?.y||0,lastAng:null,lastHit:-99,target:null,targetCd:1.2,stopUntil:0,beatUntil:0,flameUntil:0,byline:null,cutbacks:0,beaten:0,ult:null,ultBoostUntil:0};if(!g.vsxRoyalThree.jude)g.vsxRoyalThree.jude={phase:'regain',engine:20,lastX:g.player?.x||0,lastY:g.player?.y||0,carry:0,carryNeed:430,secondBall:null,secondCd:1.8,arrival:null,counterTarget:null,counterUntil:0,cycles:0,ult:null,momentum:0,finalZone:null,supportCd:0};return g.vsxRoyalThree}
function resetRT(g=game){if(!g)return;g.vsxRoyalThree=null;rtState(g)}
function growthWave(g=game){const st=rtState(g);return clamp(st?.growthOverride||g?.wave||1,1,10)}
function paceFactor(g=game){return 1.5+2.5*(growthWave(g)-1)/9}
function judeFactor(g=game){return 1+4*(growthWave(g)-1)/9}
function targetStrong(g,range=900){if(g.boss&&!g.boss.dead)return g.boss;if(g.miniBoss&&!g.miniBoss.dead)return g.miniBoss;const arr=(g.grid?.queryCircle?.(g.player.x,g.player.y,range)||[]).filter(e=>!e.dead&&!e.isCaptive);return arr.sort((a,b)=>(Number(b.elite)-Number(a.elite))+(b.maxHp||b.hp)-(a.maxHp||a.hp))[0]||g.findNearest(g.player.x,g.player.y,range)}
function src(id,tags=['football']){return{id,def:{tags}}}
function proj(g,w,x,y,angle,stats,extra={}){const q=new Projectile({x,y,vx:Math.cos(angle)*(extra.speed||stats.speed||650),vy:Math.sin(angle)*(extra.speed||stats.speed||650),radius:extra.radius||stats.size||6,damage:extra.damage||stats.damage,life:extra.life||1.25,color:extra.color||'#f6f5ee',weapon:w,pierce:extra.pierce??stats.pierce??1,knockback:extra.knockback??stats.knockback??35,behavior:extra.behavior,curveTarget:extra.curveTarget,curveStrength:extra.curveStrength,explosionRadius:extra.explosionRadius||0,projectileStyle:'football'});g.projectiles.push(q);return q}

/* Signature weapons */
ATTACK_BEHAVIORS.rmExpressFinish=function(w,s){const g=game,p=g.player,t=targetStrong(g,s.range||780);if(!t)return;const st=rtState(g).mbappe,a=Math.atan2(t.y-p.y,t.x-p.x),move=g.lastMoveDir||{x:1,y:0},mAng=Math.atan2(move.y,move.x),cut=Math.abs(angleDiff(a,mAng))>.52;let label='NEAR-POST SNAP',curve=0,damage=s.damage,speed=s.speed,pierce=s.pierce;if(st.openUntil>g.time){label='TOP CORNER';damage*=1.45;speed*=1.18;pierce+=2;curve=7.8}else if(cut){label='CUT INSIDE';damage*=1.15;curve=5.5}else if(Math.abs(angleDiff(a,mAng))>.25){label='FAR-POST CURL';curve=4.6}proj(g,w,p.x,p.y,a+(curve?0.55:0),s,{damage,speed,pierce,behavior:curve?'curveBall':undefined,curveTarget:t,curveStrength:curve,explosionRadius:label==='TOP CORNER'?54:0,color:label==='TOP CORNER'?'#f1d87a':'#f6f5ee'});if(Math.random()<.28)g.texts.push(new FloatingText(p.x,p.y-38,label,label==='TOP CORNER'?'#f1d87a':'#cfdfff',10));};
ATTACK_BEHAVIORS.rmTouchlineBlade=function(w,s){const g=game,p=g.player,st=rtState(g).vini,t=targetStrong(g,s.range||720);if(!t)return;const mv=g.lastMoveDir||{x:1,y:0},ma=Math.atan2(mv.y,mv.x),ta=Math.atan2(t.y-p.y,t.x-p.x);if(st.byline&&st.byline.ready){const bx=st.byline.x,by=st.byline.y,a=Math.atan2(t.y-by,t.x-bx);proj(g,w,bx,by,a,s,{damage:s.damage*1.32,pierce:s.pierce+2,speed:s.speed*1.08,behavior:'curveBall',curveTarget:t,curveStrength:5.8,explosionRadius:48,color:'#e9cc78'});st.byline.ready=false;st.cutbacks++;if(st.ult){st.ult.cutbacks++;st.ult.nodes.push({x:bx,y:by})}g.texts.push(new FloatingText(bx,by-24,L('CUTBACK','TRẢ NGƯỢC'),'#e9cc78',11));if(!t.isBoss&&!t.isMiniBoss&&!t.elite){g.effects.push(new PulseDelayEffect(.16,()=>{const t2=g.findNearest?.(t.x,t.y,430,t.id);if(t2&&!t2.dead){const a2=Math.atan2(t2.y-t.y,t2.x-t.x);proj(g,w,t.x,t.y,a2,s,{damage:s.damage*.72,pierce:1,speed:s.speed*.96,color:'#c9bdff'});g.texts.push(new FloatingText(t.x,t.y-20,L('SECOND TOUCH','CHẠM HAI'),'#c9bdff',9))}}))}return}const diff=Math.abs(angleDiff(ta,ma));if(diff>.75){proj(g,w,p.x,p.y,ma,s,{damage:s.damage*1.15,pierce:s.pierce+1,speed:s.speed,behavior:'curveBall',curveTarget:t,curveStrength:5.1,color:'#f4f2ee'});if(Math.random()<.25)g.texts.push(new FloatingText(p.x,p.y-34,L('CUT INSIDE','CẮT VÀO TRONG'),'#e9cc78',10))}else proj(g,w,p.x,p.y,ta,s,{damage:s.damage,speed:s.speed,pierce:s.pierce,color:'#f4f2ee'});};
ATTACK_BEHAVIORS.rmMidfieldCommand=function(w,s){const g=game,p=g.player,st=rtState(g).jude,t=targetStrong(g,s.range||680);if(st.phase==='regain'){g.effects.push(new WaveEffect(p.x,p.y,110,.32,s.damage*.65,65,w,'rgba(221,216,255,.24)'));return}if(st.phase==='carry'){if(!t)return;const a=Math.atan2(t.y-p.y,t.x-p.x);proj(g,w,p.x,p.y,a,s,{damage:s.damage*1.08,pierce:s.pierce+2,speed:s.speed*1.08,color:'#ddd8ff'});return}if(st.phase==='arrive'&&st.arrival){g.explosion(st.arrival.x,st.arrival.y,78,s.damage*1.45,'#e9cc78',95,w,false,true);return}if(t){const a=Math.atan2(t.y-p.y,t.x-p.x);proj(g,w,p.x,p.y,a,s,{damage:s.damage,pierce:s.pierce,color:'#f2f0ec'})}};

/* Character growth. Recalc is authoritative, so the wave scaling never compounds. */
const RECALC_BASE=Player.prototype.recalc;
Player.prototype.recalc=function(){
  const prevHp=this.hp,prevMax=Math.max(1,this.maxHp||100),ratio=clamp(prevHp/prevMax,0,1),r=RECALC_BASE.apply(this,arguments);
  if(!isReal(game))return r;
  const id=game.characterId,st=rtState(game);
  if(id==='rm_mbappe_k10'||id==='rm_vini_v7'){
    let factor=paceFactor(game);
    if(id==='rm_mbappe_k10'){
      const s=st.mbappe;
      if(s.secondGearUntil>game.time)factor*=1.16;
      if(s.firstStepUntil>game.time)factor*=1.10;
      if(s.ult)factor*=1+Math.min(.35,(s.ult.breaks||0)*.07);
      factor=Math.min(4,factor);
      if((s.ultBoostUntil||0)>game.time)factor=5;
    }else{
      const s=st.vini;
      if(s.flameUntil>game.time){factor*=1.10;this.attackSpeed*=1.16}
      if(s.target&&Math.hypot(s.target.x-this.x,s.target.y-this.y)<130){this.dodge=Math.min(.42,this.dodge+.06);this.attackSpeed*=1.07}
      factor=Math.min(4,factor);
      if((s.ultBoostUntil||0)>game.time)factor=5;
    }
    this.moveSpeed*=factor;
  }else if(id==='rm_jude_j5'){
    const f=judeFactor(game),base=this.maxHp,s=st.jude,eng=clamp(s.engine||0,0,100)/100;
    this.maxHp=Math.max(base,Math.round(base*f));
    this.hp=clamp(ratio*this.maxHp,0,this.maxHp);
    this.damageReduction=Math.min(.80,1-(1-this.damageReduction)/f);
    this.moveSpeed*=1.5;
    this.attackSpeed*=1+.18*eng;
    this.knockbackMultiplier*=1+.12*eng;
    if(s.ult){const mm=Math.min(5,s.ult.momentum||0);this.attackSpeed*=1+mm*.05;this.damageReduction=Math.min(.80,this.damageReduction+mm*.025)}
  }
  return r
};

function spawnHighLine(g,forced=false){const s=rtState(g).mbappe,p=g.player,m=g.lastMoveDir||{x:1,y:0};const near=(g.grid?.queryCircle?.(p.x,p.y,300)||[]).filter(e=>!e.dead&&!e.isCaptive);if(!forced&&near.length<4)return false;const side={x:-m.y,y:m.x};s.line={x:p.x+m.x*170,y:p.y+m.y*170,dx:side.x,dy:side.y,r:52,age:0,life:2.2,onAt:.5};s.lineCd=(s.ult?.time>0)?0.65:4.3;return true}
function breakHighLine(g){const s=rtState(g).mbappe,l=s.line;if(!l)return;if(l.age<l.onAt){s.offside++;if(s.ult)s.ult.offside=(s.ult.offside||0)+1;s.space=Math.max(0,s.space-12);g.texts.push(new FloatingText(g.player.x,g.player.y-46,L('OFFSIDE!','VIỆT VỊ!'),'#ff7f91',14));s.line=null;return}s.breaks++;s.space=Math.min(100,s.space+24);s.openUntil=g.time+2.5;if(s.ult){s.ult.breaks++;s.ult.route.push({x:g.player.x,y:g.player.y})}g.texts.push(new FloatingText(g.player.x,g.player.y-46,L('ONSIDE BREAK','PHÁ BẪY ĐÚNG NHỊP'),'#e9cc78',13));g.effects.push(new WaveEffect(g.player.x,g.player.y,72,.28,0,0,src('rm_line_break'),'rgba(233,204,120,.28)'));s.line=null}
function chooseViniTarget(g){const s=rtState(g).vini,p=g.player,cands=(g.grid?.queryCircle?.(p.x,p.y,330)||[]).filter(e=>!e.dead&&!e.isCaptive&&!e.isBoss);let best=null,score=-1e9;for(const e of cands){const crowd=(g.grid?.queryCircle?.(e.x,e.y,105)||[]).filter(x=>!x.dead&&!x.isCaptive).length;const d=Math.hypot(e.x-p.x,e.y-p.y);const sc=100-crowd*16-d*.05+(e.elite?18:0);if(sc>score){score=sc;best=e}}s.target=best;s.targetCd=best?3.2:1.2;return best}
