function startUlt(g,id,time,data={}){g.ultimateCharge=0;g._ultReadyAnnounced=false;g.ultimateActive=true;g.stats&&(g.stats.ultimates++);g.ultimateBuff={id:'royal_'+id,time};g.ultimateBuffTimer=time;g.vsxUltDurationTimer={id,mode:'timed',total:time,remaining:time,bound:null,synthetic:true};VSX.announce?.(t('ultimate'),ULT_INFO[id]?.name?.[VSX.lang]||id,'#cdbfff');g.player?.recalc?.();return data}
