function finishViniUlt(g){const s=rtState(g).vini,u=s.ult;if(!u)return;const source=src('rm_chaos_left',['ultimate','football','projectile']),nodes=u.nodes.slice(-8),t=targetStrong(g,950);nodes.forEach((q,i)=>g.effects.push(new PulseDelayEffect(i*.06,()=>g.explosion(q.x,q.y,55,20*g.player.damageMultiplier,'#e9cc78',55,source,false,true))));if(t)g.effects.push(new PulseDelayEffect(nodes.length*.06+.1,()=>g.explosion(t.x,t.y,u.beaten>=7&&u.cutbacks>=4?125:95,(u.beaten>=7?100:76)*g.player.damageMultiplier,'#6f52d9',120,source,false,true)));if(t)g.texts.push(new FloatingText(t.x,t.y-t.size-16,u.beaten>=7&&u.cutbacks>=4&&u.noHit?L('UNPLAYABLE','KHÔNG THỂ CẢN'):L('CHAOS ON THE LEFT','HỖN LOẠN CÁNH TRÁI'),'#e9cc78',15));s.ult=null;s.heat=45;finishCommon(g,U.vini)}
