const ULT_BASE=Game.prototype.useUltimate;
Game.prototype.useUltimate=function(){
  const id=CHARACTER_DEFINITIONS[this.characterId]?.ultimate;
  if(!Object.values(U).includes(id))return ULT_BASE.apply(this,arguments);
  if(this.state!=='PLAYING'||this.ultimateCharge<100||this.ultimateActive)return;
  const st=rtState(this);
  if(id===U.mbappe){
    const u=startUlt(this,id,9,{time:9,max:9,breaks:0,route:[],offside:0,noHit:true});
    st.mbappe.ult=u;st.mbappe.space=100;st.mbappe.lineCd=0;st.mbappe.ultBoostUntil=this.time+3;
    this.player?.recalc?.();this.texts?.push?.(new FloatingText(this.player.x,this.player.y-58,L('MAX BURST ×5.0','SIÊU TỐC ×5.0'),'#e9cc78',12));return
  }
  if(id===U.vini){
    const u=startUlt(this,id,10,{time:10,max:10,beaten:0,cutbacks:0,nodes:[],noHit:true});
    st.vini.ult=u;st.vini.heat=100;st.vini.targetCd=0;st.vini.ultBoostUntil=this.time+3;
    this.player?.recalc?.();this.texts?.push?.(new FloatingText(this.player.x,this.player.y-58,L('MAX BURST ×5.0','SIÊU TỐC ×5.0'),'#e9cc78',12));return
  }
  const u=startUlt(this,id,12,{time:12,max:12,momentum:0,final:false,finalTime:0,noHit:true});st.jude.ult=u;st.jude.momentum=0;return
};

